function renderBodyboard(){if(!project)return;const h=$('bodyboard');h.replaceChildren();h.append(sv('rect',{x:0,y:7,width:1100,height:220,rx:8,fill:'#ece9dd'}));h.append(sv('rect',{x:993,y:25,width:36,height:176,rx:5,fill:'#7d8b77'}));h.append(sv('line',{x1:1010,y1:30,x2:1010,y2:196,stroke:'#dedac8','stroke-width':6}));h.append(sv('text',{x:1010,y:218,'text-anchor':'middle','font-size':10,fill:'#6d7f72'},tr('CHEVALET','BRIDGE')));
 for(let i=0;i<6;i++){const y=liveY(i);h.append(sv('line',{x1:55,y1:y,x2:1010,y2:y,stroke:'#86917d','stroke-width':1+(5-i)*.3,'data-body-string':i,opacity:project.strings.items[i].muted?.25:1}));h.append(sv('text',{x:24,y:y+4,'text-anchor':'middle','font-size':10,fill:'#788570'},noteName(project.strings.items[i].midi)));h.append(sv('rect',{x:55,y:y-13,width:930,height:26,fill:'transparent','data-live-string':i,class:'live-hit',tabindex:0,role:'button','aria-label':tr('Pincer la corde ','Pluck string ')+(6-i)}));}
 const x=liveX(project.excitation.position);h.append(sv('line',{x1:x,y1:31,x2:x,y2:197,stroke:'#ca7d45','stroke-dasharray':'4 4','pointer-events':'none'}));h.append(sv('path',{d:`M ${x-10} 13 Q ${x} 1 ${x+10} 13 L ${x} 31 Z`,fill:'#ca7d45','data-attack-handle':'1',style:'cursor:ew-resize'}));h.append(sv('rect',{x:x-18,y:0,width:36,height:33,fill:'transparent','data-attack-handle':'1',style:'cursor:ew-resize'}));h.append(sv('text',{x,y:218,'text-anchor':'middle','font-size':10,fill:'#b36d43'},tr('ATTAQUE · ','ATTACK · ')+sig(project.excitation.position)+' mm'));
 if(liveDrag?.kind==='pull')h.append(sv('path',{d:`M55 ${liveY(liveDrag.string)} L${x} ${liveDrag.y} L1010 ${liveY(liveDrag.string)}`,stroke:'#c67440','stroke-width':2,fill:'none','pointer-events':'none'}));}
function noteName(m){return ['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'][Math.round(m)%12]+(Math.floor(m/12)-1);}
function fretClick(e){if(e.target.dataset.mute!==undefined){toggleMute(+e.target.dataset.mute);return}if(e.target.dataset.fret!==undefined){const i=Number(e.target.dataset.string),f=Number(e.target.dataset.fret);selectedString=i;project.strings.items[i].muted=false;project.strings.items[i].fret=project.strings.items[i].fret===f?0:f;changed('strings');}}
$('fretboard').onclick=fretClick;$('fretboard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fretClick(e)}};
function bodyPoint(e){const r=$('bodyboard').getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*1100,y:(e.clientY-r.top)/r.height*235};}
$('bodyboard').addEventListener('pointerdown',e=>{if(!live.ready()||audioBusy)return;e.preventDefault();const p=bodyPoint(e);if(playing)stopAudio();$('bodyboard').setPointerCapture(e.pointerId);action(async()=>{await ensureAudio();live.warmBuffers()})();if(e.target.dataset.attackHandle){liveDrag={kind:'position'};return}const i=Math.max(0,Math.min(5,5-Math.round((p.y-45)/28)));liveDrag={kind:$('gestureMode').value,string:i,startY:p.y,y:p.y,played:new Set()};if(liveDrag.kind==='strum'){playLive(i);liveDrag.played.add(i)}renderBodyboard();});
$('bodyboard').addEventListener('pointermove',e=>{if(!liveDrag)return;const p=bodyPoint(e);if(liveDrag.kind==='position'){project.excitation.position=Math.max(5,Math.min(450,Math.round((1010-p.x)/2.1)));live.bank=null;renderBodyboard();}else if(liveDrag.kind==='pull'){liveDrag.y=Math.max(15,Math.min(215,p.y));renderBodyboard();}else{const i=Math.max(0,Math.min(5,5-Math.round((p.y-45)/28))),from=liveDrag.string,step=i>=from?1:-1;for(let j=from;j!==i+step;j+=step)if(!liveDrag.played.has(j)){playLive(j);liveDrag.played.add(j)}liveDrag.string=i;}});
$('bodyboard').addEventListener('pointerup',()=>{if(!liveDrag)return;const d=liveDrag;liveDrag=null;if(d.kind==='position'){renderAllControls();changed('excitation')}else if(d.kind==='pull'){const strength=Math.max(.1,Math.min(3,Math.abs(d.y-d.startY)/25));playLive(d.string,strength)}renderBodyboard();});
$('bodyboard').addEventListener('pointercancel',()=>{const moved=liveDrag?.kind==='position';liveDrag=null;if(moved){renderAllControls();changed('excitation')}renderBodyboard()});
$('bodyboard').onkeydown=action(async e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.liveString!==undefined){e.preventDefault();if(playing)stopAudio();await ensureAudio();live.warmBuffers();playLive(+e.target.dataset.liveString)}});
function animateString(i){for(const selector of [`#fretboard [data-vibrates='${i}']`,`#bodyboard [data-body-string='${i}']`])document.querySelector(selector)?.animate([{transform:'translateY(0)'},{transform:'translateY(3px)'},{transform:'translateY(-2px)'},{transform:'translateY(1px)'},{transform:'translateY(0)'}],{duration:220});}
function decode(b64){const raw=atob(b64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Float32Array(bytes.buffer);}
function acousticStrings(p=project){const s=clone(p.strings);s.items.forEach(a=>delete a.muted);return s}
function toggleMute(i){const s=project.strings.items[i];s.muted=!s.muted;if(s.muted)live.mute(i);changed('mute')}
function playLive(i,strength=1,delay=0){if(!live.ready()||audioBusy)return false;return !project.strings.items[i].muted&&live.play(i,strength,delay)}
function liveSignature(){if(!isReady())return null;return JSON.stringify([job,acousticStrings(),project.excitation,project.synthesis,project.modalEdits,project.hole.endFactor,project.hole.resistance,project.monitor.point,selectedString]);}
function liveStatus(state,error){
 const busy=(state==='preparing'||state==='dirty'||audioBusy)&&state!=='missing'&&state!=='error';
 const ready=['ready','playing','unlock'].includes(state)&&!audioBusy;
 const messages={ready:['Prêt à jouer','Ready to play'],playing:['Prêt à jouer','Ready to play'],unlock:['Prêt à jouer','Ready to play'],dirty:['Préparation en cours — veuillez patienter','Preparation in progress — please wait'],preparing:['Préparation en cours — veuillez patienter','Preparation in progress — please wait'],missing:['Calcul EF requis','FE solve required'],error:['Préparation impossible','Preparation failed']};
 const message=tr(...(messages[state]||messages.dirty));
 $('audioState').textContent=message;
 $('preparationTitle').textContent=audioBusy?tr('Préparation de la phrase — veuillez patienter','Preparing phrase — please wait'):message;
 $('stringPreparation').classList.toggle('ready',ready);
 $('stringPreparation').setAttribute('aria-busy',String(busy));
 $('preparationProgress').hidden=!busy;
 $('preparationDetail').textContent=error?error.message:ready?tr('Pincez une corde ou grattez l’accord.','Pluck a string or strum the chord.'):state==='missing'?tr('Lancez « Mailler & calculer EF ».','Run “Mesh & solve FE”.'):state==='error'?tr('Relancez avec « Préparer les sons ».','Retry with “Prepare sounds”.'):tr('Les commandes de jeu seront disponibles à la fin du calcul.','Playing controls will become available when calculation finishes.');
 for(const id of ['strum','phrase','repertoirePlay'])$(id).disabled=!ready;
 $('bodyboard').setAttribute('aria-disabled',String(!ready));
 $('bodyboard').inert=!ready;
 $('prepareLive').disabled=busy||state==='missing';
 if(error)toast(error.message,true);
}
const live=new LiveStrings({context:()=>audioContext,signature:liveSignature,monitor:()=>project.monitor,onStatus:liveStatus,onAnimate:animateString,
 prepare:async()=>{const p=clone(project),port=selectedString,r=await api('/api/audio-bank',{id:job,project:p,selected:port});return {...r,project:p,...Object.fromEntries(['force','velocity','pressure'].map(k=>[k,r[k].map(decode)]))}},
 onTake:r=>{take=r;playOffset=0;project.analysis.tmin=0;project.analysis.tmax=r.duration;delete project.analysis.selection;renderAudio();}});
$('prepareLive').onclick=action(async()=>{await ensureAudio();await live.prepare();live.warmBuffers()});
$('livePort').onchange=()=>{selectedString=+$('livePort').value;renderFretboard();live.invalidate()};
let audioBusy=false;const audioCache=new Map();
async function pluck(events,repertoireMode=false){
 if(audioBusy)return;if(!isReady())throw new Error(tr('Lancer « Mailler & calculer EF » avant l’écoute.','Run “Mesh & solve FE” before listening.'));
 audioBusy=true;stopAudio();liveStatus('preparing');const token=audioToken,id=job,epoch=modelEpoch,start=performance.now(),p=clone(project),port=selectedString;
 const key=JSON.stringify([id,p.strings,p.excitation,p.synthesis,p.modalEdits,p.hole.endFactor,p.hole.resistance,p.monitor.point,port,events,repertoireMode]);
 try{
  await ensureAudio();if(token!==audioToken)return;$('audioState').textContent=tr('Synthèse…','Synthesising…');
  let r=audioCache.get(key);if(!r)r=await api('/api/audio',{id,project:p,selected:port,events,repertoire:repertoireMode});
  if(token!==audioToken||epoch!==modelEpoch||id!==job||!isReady()||responseSignature(p)!==responseSignature()||JSON.stringify(p.excitation)!==JSON.stringify(project.excitation)||port!==selectedString)return;
  audioCache.set(key,r);while(audioCache.size>3||[...audioCache.values()].reduce((n,a)=>n+a.force.length+a.velocity.length+a.pressure.length,0)>32000000)audioCache.delete(audioCache.keys().next().value);
  take={...r,force:decode(r.force),velocity:decode(r.velocity),pressure:decode(r.pressure),project:p,events,elapsed:(performance.now()-start)/1000};playOffset=0;project.analysis.tmin=0;project.analysis.tmax=take.duration;delete project.analysis.selection;
  renderAudio();await playTake();events.forEach(ev=>setTimeout(()=>{if(token===audioToken&&playing)animateString(ev.string);},ev.time*1000));return take;
 }finally{audioBusy=false;status();}
}
async function ensureAudio(){audioContext??=new (window.AudioContext||window.webkitAudioContext)();await AppUX.resumeAudio(audioContext);}
function listenSamples(){if(!take)return null;const input=playbackRegion?.samples||take[project.monitor.source],monitor={...project.monitor,level:analysisPlayback?project.analysis.volume:project.monitor.level};return listening(input,take.sr,monitor);}
function updatePlaybackGain(){
 if(!playMetrics||!audioGain)return;const monitor={...project.monitor,level:analysisPlayback?project.analysis.volume:project.monitor.level},g=playbackGain(playMetrics,monitor);
 audioGain.gain.setTargetAtTime(g.gain/playMetrics.baseGain,audioContext.currentTime,.015);
 $('gainInfo').textContent=g.reductionDB>.05?tr('Protection crête : gain réduit de ','Peak protection: gain reduced by ')+sig(g.reductionDB)+' dB.':tr('Écoute : marge de crête conservée.','Playback: peak headroom retained.');
}
const takeBuffers=new WeakMap();
function makeTakeBuffer(samples,sr,stats){let peak=stats?.peak,sum=0;if(!Number.isFinite(peak)){peak=0;for(const x of samples){peak=Math.max(peak,Math.abs(x));sum+=x*x}}peak=Math.max(peak,1e-12);const metrics={peak,rms:stats?.rms??Math.sqrt(sum/Math.max(1,samples.length)),baseGain:.9/peak};const buffer=audioContext.createBuffer(1,samples.length,sr);buffer.copyToChannel(Float32Array.from(samples,x=>x*metrics.baseGain),0);return {buffer,metrics}}
function takeBuffer(t,source){let cached=takeBuffers.get(t);if(!cached){cached={};takeBuffers.set(t,cached)}return cached[source]??=makeTakeBuffer(t[source],t.sr,t.stats?.[source])}
async function playTake(){
 if(!take)return;const token=++playToken,current=take;await ensureAudio();if(token!==playToken||current!==take)return;
 if(audioNode){audioNode.onended=null;audioNode.stop();audioNode.disconnect?.();}audioGain?.disconnect?.();
 const start=playbackRegion?.start||0,prepared=playbackRegion?makeTakeBuffer(playbackRegion.samples,take.sr):takeBuffer(take,project.monitor.source);playMetrics=prepared.metrics;const b=prepared.buffer;
 audioNode=audioContext.createBufferSource();audioNode.buffer=b;audioGain=audioContext.createGain();audioNode.connect(audioGain);audioGain.connect(audioContext.destination);audioGain.gain.value=playbackGain(playMetrics,{...project.monitor,level:analysisPlayback?project.analysis.volume:project.monitor.level}).gain/playMetrics.baseGain;updatePlaybackGain();
 if(playOffset<start||playOffset>=start+b.duration)playOffset=start;playStarted=audioContext.currentTime-playOffset;playing=true;
 audioNode.onended=()=>{playing=false;playOffset=0;playbackRegion=null;transportLabels();};audioNode.start(0,playOffset-start);transportLabels();
}
function stopAudio(capture=true){if(capture&&live.records.length&&live.ready())live.capture();live.stop();++audioToken;++playToken;if(audioNode){audioNode.onended=null;try{audioNode.stop();}catch{}audioNode.disconnect?.();audioNode=null;}audioGain?.disconnect?.();audioGain=null;playMetrics=null;playing=false;playOffset=0;playbackRegion=null;analysisPlayback=false;transportLabels();}
function pauseAudio(){if(live.voices.length){const offset=audioContext.currentTime-live.started-(live.records[0]?.time||0);live.capture();live.stop();playOffset=Math.max(0,offset);playing=false;transportLabels();return;}if(!take)return;++playToken;if(playing){playOffset=audioContext.currentTime-playStarted;audioNode.onended=null;audioNode.stop();audioNode.disconnect?.();audioNode=null;playing=false;transportLabels();}else action(playTake)();}
function renderAudio(){
 if(!take)return;const source=project.monitor.source,samples=take[source],stats=take.stats[source],unit={force:'N',velocity:'m/s',pressure:'Pa'}[source],band=take.synthesisBand||[0,take.band];
 $('audioInfo').textContent=`${take.project.name} · ${sig(take.duration)} s · ${sig(take.sr/1000,4)} kHz · ${tr('crête','peak')} ${sig(stats.peak)} ${unit} · RMS ${sig(stats.rms)} ${unit} · ${tr('bande','band')} ${sig(band[0])}–${sig(band[1])} Hz · ${take.projection?tr('projection résiduelle','residual projection'):tr('modes seuls','modes only')}.`;
 const {x,y}=waveformEnvelope(samples,take.sr,1200);
 wavePlot.x=[0,take.duration];wavePlot.y=[-stats.peak*1.05||-1,stats.peak*1.05||1];wavePlot.ylabel=unit;wavePlot.curves=[{x,y,color:'#4d8376'}];wavePlot.draw();
 const spec=spectrum(samples,8192,Math.max(0,Math.min(Math.round(.05*take.sr),samples.length-8192))),freq=Array.from(spec,(_,i)=>i*take.sr/8192),max=Math.max(...spec);
 spectrumPlot.x=[project.analysis.fmin,project.analysis.fmax];spectrumPlot.y=[max-100,max+5];spectrumPlot.band=take.band;spectrumPlot.ylabel='dB re 1 '+unit;spectrumPlot.curves=[{x:freq,y:spec,color:'#b1764d'}];spectrumPlot.draw();renderAnalysis();
}
function renderHelp(){const fr=`<h2>Guide d’utilisation</h2><p>GMT explore les liens entre lutherie, mobilité et son. Les contours de référence de GMT 1.6 sont restaurés. Sources et conditions de redistribution : CONTOURS.md et PUBLICATION.md.</p><h3>Contours et pan coupé</h3><p>Dans Atelier → Géométrie : aucun, Épaulement, vénitien archtop arrondi ou florentin de type ES-175. Choisir le côté et la profondeur. Le pan coupé modifie la table, le fond, les éclisses, le volume d’air et le calcul EF. Le tracé est conservé à ses dimensions ; aucune remise à l’échelle automatique ne suit la découpe. Recalculer les FRF après modification. L’import SVG conserve la découpe déjà dessinée et désactive le pan coupé additionnel par défaut.</p><h3>Modes, contacts et analyse</h3><p>La vue Maillage & modes inclut les faces intérieures des barrages. Les franges représentent |u| ou une composante signée, normalisée ; les valeurs sont interpolées avec les fonctions quadratiques des faces TET10. Masquer table et fond ou utiliser Vue intérieure pour voir les barres. Les six points de corde sont repérés sur le chevalet. Dans Réponses FRF, choisir caisse + air ou chargement des six cordes et afficher six courbes séparées.</p><p>La bande modale est limitée par son budget de modes. La projection résiduelle ajoute des vecteurs calculés à partir de la flexibilité statique EF aux points de corde ; son amortissement est un réglage d’approximation. L’onglet Spectrogramme règle FFT, fenêtre, axes temps/fréquence, palettes et dynamique. Un rectangle sélectionne une durée et une bande à écouter ou exporter ; pause et reprise conservent la position.</p><h3>Un premier parcours</h3><ol><li>Choisir une famille et un gabarit. Ajuster les épaisseurs, le contour, les barrages et le chevalet dans l’Atelier. Deux clics ajoutent une barre ; ses poignées déplacent les extrémités.</li><li>Choisir les essences et les directions du bois. Les valeurs proposées sont illustratives : remplacer les constantes par des mesures pour étudier une pièce réelle.</li><li>Mailler et calculer. Affiner la taille et augmenter les modes pour vérifier la convergence des fréquences et des FRF.</li><li>Écouter une corde, un accord librement placé sur le manche ou la phrase originale de comparaison. La force, la vitesse et la pression sont trois signaux distincts.</li><li>Mémoriser A, modifier la lutherie, recalculer et mémoriser B. Utiliser le gain fixe pour conserver les écarts de niveau ; la normalisation de crête les efface.</li></ol><h3>Ce qui est calculé</h3><p>Gmsh construit des volumes fragmentés avec nœuds partagés. Le bois utilise des tétraèdres quadratiques TET10 en élasticité orthotrope, l’air des TET4 de pression. La cavité inclut l’épaisseur de l’ouverture. Une correction d’extrémité et des pertes complètent l’impédance de bouche. La réduction modale conserve le couplage fluide–structure et douze ports : six normaux et six transversaux au chevalet.</p><p class="equation">Mobilité : Y = v/F · m·s⁻¹/N<br>Transfert acoustique : H = p(P)/F · Pa/N<br>Couplage des cordes : F = (I + Z<sub>cordes</sub> Y)<sup>−1</sup> F<sub>bloquée</sub></p><p>Le pincement est une déformée initiale statique sous une force ponctuelle, lissée par la largeur et la dureté de contact. La raideur de flexion, l’amortissement et le chargement mutuel par la caisse sont pris en compte. L’angle décompose le geste selon les deux directions calculées. Le manche sert à choisir des notes, sans calcul mécanique du manche.</p><h3>Lire les résultats avec leurs limites</h3><p>Les assemblages sont parfaitement collés. Les profils de barres utilisent trois segments de hauteur. Les croisements adoptent l’orientation du premier volume. Le bombé est une transformation géométrique lisse ; il ne simule ni fabrication ni contraintes résiduelles. Le modèle ne calcule pas la précontrainte sous tension des cordes, le décollement, les colles souples ni la torsion des cordes.</p><p>Les essais de raffinement de la version 1.0 ont montré une variation du premier mode OM de 2,56 % entre 20 et 15 mm. La convergence des nouveaux contours reste à établir. Les rapports détaillés sont dans VERIFICATION.md. Les constantes du bois et des cordes sont des points de départ, pas des fiches commerciales certifiées. La pression est une approximation en champ libre par panneaux monopôles et débit d’ouverture, sans BEM extérieur, salle, ni calibration SPL. La distance minimale au panneau est de 30 mm. La bande de calcul modal et la bande de synthèse sont indépendantes. Au-delà de la base calculée, la zone ombrée utilise une projection résiduelle EF si elle est activée ; les résonances manquantes ne sont pas résolues. Le passe-bas automatique lié au dernier mode a été supprimé. La bande de synthèse choisie s’applique aux signaux physiques et à l’écoute.</p><p>Les poignées de FRF effectuent des variations modales virtuelles de fréquence, amortissement et participation. Elles ne reconstruisent aucune géométrie équivalente. Un nouveau calcul EF est requis pour attribuer un effet à une modification de lutherie.</p><h3>Fichiers & utilisation</h3><p>Les sessions JSON conservent les paramètres et les comparaisons A/B. Les maillages MSH/VTK et les modes NPZ sont exportables. Le WAV physique est mono float32 en N, m/s ou Pa ; ses valeurs ne sont pas un niveau audio calibré. Le WAV PCM16 contient le signal d’écoute limité à 0,9 FS. Tout fonctionne localement après installation des dépendances. Aucune connexion n’est nécessaire à l’usage.</p><h3>Sources & crédits</h3><p>Principe de pincement dans la continuité de PickupTool Lab. Modèle GMT indépendant de sa chaîne électrique. Géométrie et mailleur : <a href="https://gmsh.info/doc/texinfo/" target="_blank" rel="noreferrer">Gmsh</a>. Orthotropie : <a href="https://research.fs.usda.gov/treesearch/62244" target="_blank" rel="noreferrer">USDA Wood Handbook, chapitre 5</a>. Couplage et rayonnement : <a href="https://euphonics.org/4-2-2-coupling-of-a-helmholtz-resonator-and-a-body-mode/" target="_blank" rel="noreferrer">Euphonics</a>. Les dimensions de famille s’appuient sur les documents de fabricants et de luthiers listés dans MODELE.md. Code GMT : GPL-3.0-or-later ; Three.js : MIT.</p>`;
const en=`<h2>User guide</h2><p>GMT explores guitar construction, bridge mobility and sound. Reference outlines are restored from GMT 1.6; attribution and content-specific conditions are listed in CONTOURS.md and PUBLICATION.md.</p><h3>Outlines and cutaway</h3><p>Workshop → Geometry offers none, Épaulement, rounded archtop Venetian or ES-175-style Florentine, with side and depth controls. The cutaway changes top, back, ribs, air volume and FE geometry. The body is not rescaled after the cut. Solve again to update FRFs. SVG import preserves a cutaway already drawn in the file and initially disables any additional cutaway.</p><h3>Modes, contacts and analysis</h3><p>The Mesh & modes view includes internal brace faces. Contours show normalised |u| or a signed component, interpolated with quadratic TET10 surface functions. Hide top/back or use Interior view to inspect braces. Six string contacts are marked on the bridge. FRF responses can show the body + air or six-string-loaded response, with one curve per contact.</p><p>The modal band is limited by its mode budget. Residual projection adds FE static-flexibility vectors driven at the string contacts; its damping is an approximation setting. The Spectrogram tab controls FFT, window, time/frequency axes, palettes and dynamic range. A rectangle selects a duration and frequency band to listen to or export. Pause/resume preserves playback position.</p><h3>A first workflow</h3><ol><li>Select a family and template. Edit thicknesses, outline, bracing and bridge in the Workshop. Two clicks add a brace; handles move its endpoints.</li><li>Select species and local wood directions. Initial properties are illustrative. Use measured constants to study a particular specimen.</li><li>Mesh and solve. Refine the mesh and retain more modes to check frequency and FRF convergence.</li><li>Listen to a string, a freely fingered chord or the original comparison phrase. Force, velocity and pressure are distinct signals.</li><li>Store A, change construction, solve and store B. Fixed playback gain retains level differences while peak protection is inactive. Any gain reduction is displayed during playback.</li></ol><h3>What is calculated</h3><p>Gmsh builds fragmented volumes with shared interface nodes. Wood uses quadratic TET10 orthotropic elastic elements; cavity pressure uses TET4 elements. The cavity includes the physical soundhole neck. External end correction and losses complete the aperture impedance. Modal reduction retains fluid–structure coupling and twelve bridge ports: six normal and six transverse.</p><p class="equation">Mobility: Y = v/F · m·s⁻¹/N<br>Acoustic transfer: H = p(P)/F · Pa/N<br>String coupling: F = (I + Z<sub>strings</sub> Y)<sup>−1</sup> F<sub>blocked</sub></p><p>The initial pluck is a static deflection under a point force, smoothed by contact width and hardness. Bending stiffness, damping and mutual body loading are included. Pluck angle resolves the gesture into both calculated directions. The fingerboard selects notes without a mechanical neck model.</p><h3>Interpretation and limits</h3><p>Joints are perfectly bonded. Brace profiles have three height segments. Crossings take the first volume’s grain orientation. Arching is a smooth geometry transformation, without manufacturing or residual stress simulation. String prestress, joint separation, compliant glue and string torsion are not calculated.</p><p>The version 1.0 refinement study showed a 2.56% change in the first OM mode between 20 and 15 mm. Mesh convergence for the new outlines remains to be established. See VERIFICATION.md in the distribution. Wood and string constants are starting values, not certified commercial specifications. Pressure uses a free-field monopole-panel and aperture-flow approximation, without exterior BEM, room response or SPL calibration. Listening points must remain at least 30 mm from panels. Modal extraction and synthesis frequency bands are independent. The shaded region uses FE residual projection when enabled; omitted resonances remain unresolved. Playback is no longer low-pass filtered at the last mode. The chosen synthesis band applies to physical outputs and playback.</p><p>FRF handles make virtual modal changes in frequency, damping and participation. They do not reconstruct an equivalent geometry. A new FE solve is needed to attribute changes to construction.</p><h3>Files and use</h3><p>JSON sessions retain parameters and A/B comparisons. MSH/VTK meshes and NPZ modes can be exported. Physical WAV is mono float32 in N, m/s or Pa, without audio-level calibration. PCM16 WAV contains the playback signal protected at 0.9 FS. After dependency installation, all processing runs locally without an internet connection.</p><h3>Sources and credits</h3><p>Pluck principles continue the work of PickupTool Lab; GMT has an independent acoustic model. Geometry and meshing: <a href="https://gmsh.info/doc/texinfo/" target="_blank" rel="noreferrer">Gmsh</a>. Orthotropy: <a href="https://research.fs.usda.gov/treesearch/62244" target="_blank" rel="noreferrer">USDA Wood Handbook, chapter 5</a>. Coupling and radiation: <a href="https://euphonics.org/4-2-2-coupling-of-a-helmholtz-resonator-and-a-body-mode/" target="_blank" rel="noreferrer">Euphonics</a>. Manufacturer and luthier dimensions are referenced in MODELE.md. GMT source: GPL-3.0-or-later; Three.js: MIT.</p>`;$('helpCopy').innerHTML=(lang==='fr'?fr:en)+tr(`<h3>Préparation et répertoire</h3><p>Après un changement physique, attendez « Prêt à jouer ». La banque des six cordes est recalculée ; volume et gain ne nécessitent pas de préparation. En cas d’échec, utilisez Préparer les sons.</p><p>Le répertoire suit le tempo choisi. Les mélodies utilisent les hauteurs écrites avec l’accordage courant ; les motifs suivent les cases indiquées et sont transposés par un autre accordage. Les notes sont synthétisées avec la caisse, les cordes, l’excitation, le point d’écoute et la bande de synthèse courants. Chaque attaque utilise une réponse linéaire avec une extinction progressive ; le changement continu de couplage sympathique pendant les changements de doigté n’est pas simulé. La durée par pincement peut raccourcir les notes. Les cordes muettes restent muettes.</p><p>Le WAV du répertoire exporte la dernière phrase terminée avec les réglages d’écoute mémorisés au démarrage de la lecture. Pour exporter de nouveaux réglages, relancer la phrase. Stop annule la lecture d’un résultat en attente ; le calcul serveur déjà engagé peut continuer.</p>`,`<h3>Preparation and repertoire</h3><p>After changing physical parameters, wait for “Ready to play”. The six-string bank is rebuilt; volume and gain do not require preparation. Use Prepare sounds to retry after an error.</p><p>Melodies use written pitches with the current tuning; original patterns follow fret positions and transpose with tuning. Rendering uses current body, strings, excitation, listening point and synthesis band. Each attack uses an independent linear response with a tapered release; continuously varying sympathetic coupling during fingering changes is not simulated. Duration per pluck may shorten notes. Muted strings remain muted.</p><p>Repertoire WAV exports the last completed phrase with the monitoring settings saved at playback start. Render again to export changed settings. Stop prevents a pending result from playing; server computation already underway may continue.</p>`);}
async function importSVG(file){if(file.size>1000000)throw new Error('SVG < 1 MB');const xml=new DOMParser().parseFromString(await file.text(),'image/svg+xml');if(xml.querySelector('parsererror'))throw new Error('SVG invalide / invalid');const safe=sv('svg',{width:500,height:600,style:'position:fixed;left:-10000px;top:0;visibility:hidden;pointer-events:none'});document.body.append(safe);let candidates=[];try{for(const src of xml.querySelectorAll('path,polygon,polyline,ellipse,circle,rect')){const kind=src.tagName,allowed={path:['d'],polygon:['points'],polyline:['points'],ellipse:['cx','cy','rx','ry'],circle:['cx','cy','r'],rect:['x','y','width','height','rx','ry']}[kind];if(!allowed)continue;const e=sv(kind);for(let key of allowed)if(src.hasAttribute(key))e.setAttribute(key,src.getAttribute(key));let parents=[],cur=src;while(cur&&cur.tagName!=='svg'){if(cur.hasAttribute?.('transform'))parents.unshift(cur.getAttribute('transform'));cur=cur.parentElement;}let group=sv('g',{transform:parents.join(' ')});group.append(e);safe.append(group);const len=e.getTotalLength();if(!Number.isFinite(len)||len<=0)continue;const matrix=e.getCTM(),pts=Array.from({length:180},(_,i)=>{let p=e.getPointAtLength(len*i/179),v=new DOMPoint(p.x,p.y).matrixTransform(matrix);return [v.x,v.y];}),w=Math.max(...pts.map(p=>p[0]))-Math.min(...pts.map(p=>p[0])),h=Math.max(...pts.map(p=>p[1]))-Math.min(...pts.map(p=>p[1]));if(Math.hypot(pts[0][0]-pts.at(-1)[0],pts[0][1]-pts.at(-1)[1])>.03*Math.max(w,h))continue;let area=Math.abs(pts.reduce((a,p,i)=>{let n=pts[(i+1)%pts.length];return a+p[0]*n[1]-n[0]*p[1];},0));candidates.push({pts,area});}if(!candidates.length)throw new Error(tr('Contour fermé introuvable dans ce SVG.','No closed outline found in this SVG.'));let pts=candidates.sort((a,b)=>b.area-a.area)[0].pts,xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);project.body.cutaway='none';project.body.outline=pts.map(([x,y])=>[(x-(xmin+xmax)/2)/(xmax-xmin)*project.body.width,(ymax-y)/(ymax-ymin)*project.body.length]);renderAllControls();changed();toast(tr('Contour importé et ajusté aux dimensions de caisse. Vérifier bouche, barres et chevalet.','Outline imported and scaled to body dimensions. Check opening, braces and bridge.'));}finally{safe.remove();}}
async function exportSVG(){const exportProject=clone(project),exportPreview=await api('/api/preview',{project:exportProject});const W=exportProject.body.width,L=exportProject.body.length,margin=15;let root=sv('svg',{xmlns:NS,width:(W+2*margin)+'mm',height:(L+45)+'mm',viewBox:`${-W/2-margin} ${-margin} ${W+2*margin} ${L+45}`}),g=sv('g',{transform:`translate(0,${L}) scale(1,-1)`,fill:'none',stroke:'black','stroke-width':.5});root.append(sv('title',{},exportProject.name+' · '+part+' · '+exportProject.body.cutaway));root.append(sv('metadata',{},JSON.stringify({units:'mm',scale:'1:1',bodyWidth:W,bodyLength:L,cutaway:exportProject.body.cutaway,depth:exportProject.body.cutawayDepth,side:exportProject.body.cutawaySide,source:exportPreview.source})));g.append(sv('path',{d:dpath(exportPreview.outline),id:'body-outline'}));if(part==='top')exportPreview.holes.forEach((h,i)=>g.append(sv('path',{d:dpath(h),id:'soundhole-'+(i+1)})));const defs=sv('defs'),clip=sv('clipPath',{id:'brace-export-clip',clipPathUnits:'userSpaceOnUse'});clip.append(sv('path',{d:dpath(exportPreview.inner)+(part==='top'?exportPreview.holes.map(dpath).join(' '):''),'clip-rule':'evenodd','fill-rule':'evenodd'}));defs.append(clip);g.append(defs);const bars=sv('g',{'clip-path':'url(#brace-export-clip)'});g.append(bars);exportProject.braces.filter(b=>b.part===part).forEach(b=>bars.append(sv('line',{x1:b.a[0],y1:b.a[1],x2:b.b[0],y2:b.b[1],stroke:'#bb7744','stroke-width':b.width})));root.append(g);root.append(sv('path',{d:`M-50 ${L+13}H50 M-50 ${L+10}V${L+16} M50 ${L+10}V${L+16}`,stroke:'black','stroke-width':.4,fill:'none'}));root.append(sv('text',{x:0,y:L+21,'text-anchor':'middle','font-size':4,'font-family':'sans-serif'},`100 mm · ${W} × ${L} mm · 1:1`));download(new XMLSerializer().serializeToString(root),filename()+'_'+exportProject.body.cutaway+'_'+part+'.svg','image/svg+xml');}
