function renderPartMeshStats(){
 const host=$('partMeshStats');host.replaceChildren();if(!lastMesh)return;const groups=new Map(),names={top:tr('Table','Top'),back:tr('Fond','Back'),ribs:tr('Éclisses','Ribs'),bridge:tr('Chevalet','Bridge')};
 for(const g of Object.values(lastMesh.groups)){const label=g.part==='braces'?(g.id==='neckblock'?tr('Bloc de manche','Neck block'):(g.id||'bar')+' · '+tr(g.side==='top'?'table':'fond',g.side==='top'?'top':'back')):names[g.part]||g.part;const entry=groups.get(label)||{tetrahedra:0,volume:0};entry.tetrahedra+=g.tetrahedra||0;entry.volume+=g.volume||0;groups.set(label,entry);}
 const table=node('table'),head=node('tr');for(const title of [tr('Pièce','Part'),'TET10','cm³'])head.append(node('th',{},title));table.append(head);
 for(const [name,g] of groups){const row=node('tr');row.append(node('td',{},name),node('td',{},String(g.tetrahedra)),node('td',{},sig(g.volume*1e6)));table.append(row);}host.append(table);
}
function renderBridgeMap(){
 const svg=$('bridgeMap');svg.replaceChildren();if(!response)return;const b=(solvedProject||project).bridge,W=b.width,D=b.depth;
 svg.setAttribute('viewBox',`${-W/2-25} ${-D/2-25} ${W+50} ${D+55}`);svg.append(sv('rect',{x:-W/2,y:-D/2,width:W,height:D,rx:2,fill:'#9b7952',stroke:'#5b5140','stroke-width':.5}));
 response.ports.forEach((p,i)=>{const selected=Number($('frfString').value)===i,x=p[0]*1000-b.x,y=p[1]*1000-b.y;const circle=sv('circle',{cx:x,cy:y,r:selected?3.8:2.8,fill:colors[i],stroke:'#fff8df','stroke-width':selected?1.5:.6});circle.style.cursor='pointer';circle.onclick=()=>{$('frfString').value=i;drawFRF();};svg.append(circle,sv('text',{x,y:y-8,'text-anchor':'middle','font-size':6,fill:colors[i],'pointer-events':'none'},String(i+1)));});
 const i=Number($('frfString').value||0),port=response.ports[i],direction=Number($('frfDirection').value)===0?'Z':'X',source=$('frfLoad').value==='strings'?tr('Caisse + air + chargement des six cordes','Body + air + six-string loading'):tr('Caisse + air, sans chargement des cordes','Body + air, without string loading');
 $('frfPortInfo').textContent=`${tr('Point','Contact')} ${i+1} · ${direction} · (${port.map(x=>sig(x*1000,4)).join(', ')}) mm. ${source}. `+($('frfType').value==='mobility'?`Y${i+1},${i+1} = v${i+1}/F${i+1}.`:`H${i+1} = p(P)/F${i+1}.`);
}
function drawSixFRFs(){
 const host=$('sixFRFs');host.hidden=!$('frfSeparate').checked;if(!response||host.hidden)return;
 if(!sixPlots.length)for(let i=0;i<6;i++){const card=node('article'),heading=node('h3'),canvas=node('canvas',{class:'plot','aria-label':'Bridge contact '+(i+1)});card.append(heading,canvas);host.append(card);sixPlots.push({heading,plot:new LinePlot(canvas)});}
 const type=$('frfType').value,offset=Number($('frfDirection').value);
 sixPlots.forEach(({heading,plot},i)=>{heading.textContent=tr('Point de corde ','String contact ')+(i+1)+' · '+noteName(project.strings.items[i].midi);heading.style.color=colors[i];plot.x=[...frfPlot.x];plot.y=[...frfPlot.y];plot.band=frfPlot.band;plot.lowerBand=frfPlot.lowerBand;plot.ylabel=type==='mobility'?'dB · m/s/N':'dB · Pa/N';plot.curves=[{x:response.frequencies,y:values(response,i+offset,type),color:colors[i]}];plot.draw();});
}
function transportLabels(){
 const label=playing?tr('Ⅱ Pause','Ⅱ Pause'):playOffset>0?tr('▶ Reprendre','▶ Resume'):tr('Ⅱ Pause','Ⅱ Pause');$('pause').textContent=label;$('analysisPause').textContent=label;
}
function cursorTime(){return take?Math.max(0,Math.min(take.duration,playing?audioContext.currentTime-playStarted:playOffset)):null;}
async function seekAudio(t){
 if(!take)return;++playToken;const wasPlaying=playing;if(audioNode){audioNode.onended=null;audioNode.stop();audioNode=null;}playing=false;playOffset=Math.max(0,Math.min(take.duration,t));
 if(playbackRegion&&(playOffset<playbackRegion.start||playOffset>=playbackRegion.end))playbackRegion=null;
 if(wasPlaying)await playTake();transportLabels();analysisView.draw();miniSpectrogram.draw();
}
function renderAnalysisControls(){
 const host=$('analysisControls');host.replaceChildren();
 select(host,'analysis.gesture','Outil de souris','Mouse tool',[['pan','Déplacer','Pan'],['select','Rectangle temps–fréquence','Time–frequency rectangle']],'analysis');
 select(host,'analysis.fft','Taille FFT','FFT size',[1024,2048,4096,8192,16384].map(x=>[String(x),String(x),String(x)]),'analysis');
 select(host,'analysis.window','Fenêtre','Window',[['hann','Hann'],['hamming','Hamming'],['blackman','Blackman'],['rect','Rectangulaire','Rectangular']],'analysis');
 select(host,'analysis.palette','Palette','Palette',[['magma','Magma'],['viridis','Viridis'],['turbo','Turbo'],['rainbow','Arc-en-ciel','Rainbow'],['balance','Bleu · blanc · rouge','Blue · white · red'],['gray','Gris','Grey']],'analysis');
 select(host,'analysis.scale','Axe fréquentiel','Frequency scale',[['linear','Linéaire','Linear'],['log','Logarithmique','Logarithmic']],'analysis');
 control(host,'analysis.range','Dynamique','Dynamic range',20,120,1,'dB','analysis');
 select(host,'analysis.reference','Référence des couleurs','Colour reference',[['peak','Crête de la prise','Take peak'],['absolute','Référence SI fixe','Fixed SI reference']],'analysis');
 control(host,'analysis.ceiling','Plafond absolu · re 1 SI','Absolute ceiling · re 1 SI',-180,80,1,'dB','analysis');
 $('analysisSource').replaceChildren(...[...$('listenSource').children].map(x=>x.cloneNode(true)));syncAnalysisAxes();
}
function syncAnalysisAxes(){
 if(!project?.analysis)return;const a=project.analysis;
 for(const [id,key] of [['analysisTmin','tmin'],['analysisTmax','tmax'],['analysisFmin','fmin'],['analysisFmax','fmax']])if(document.activeElement!==$(id))$(id).value=key[0]==='t'?Number(Number(a[key]).toFixed(3)):Number(Number(a[key]).toFixed(1));
 $('analysisVolume').value=a.volume;$('fftSize').value=a.fft;$('specMax').value=a.fmax;$('specRange').value=a.range;
 const sel=a.selection;$('analysisSelectionInfo').textContent=sel?`${tr('Sélection','Selection')} · ${sig(sel.t0,4)}–${sig(sel.t1,4)} s · ${sig(sel.f0,4)}–${sig(sel.f1,4)} Hz`:tr('Aucune sélection.','No selection.');
}
function renderAnalysis(){
 if(!project)return;const source=project.monitor.source;$('analysisSource').value=source;
 if(!take){syncAnalysisAxes();return;}
 const samples=take[source],a=project.analysis,unit={force:'N',velocity:'m/s',pressure:'Pa'}[source];analysisView.setData(samples,take.sr);miniSpectrogram.setData(samples,take.sr);syncAnalysisAxes();
 $('analysisSeek').max=take.duration;$('analysisResolution').textContent=`Δf = ${sig(take.sr/Number(a.fft))} Hz · ${sig(Number(a.fft)/take.sr*1000)} ms · ${a.window}. `+(a.reference==='absolute'?`dB re 1 ${unit}.`:tr('Couleurs référencées à la crête de la prise.','Colours referenced to the take peak.'));
 const band=take.synthesisBand||[0,take.band];$('analysisBand').textContent=`${tr('Synthèse','Synthesis')} : ${sig(band[0])}–${sig(band[1])} Hz. ${tr('Dernier mode EF','Last FE mode')} : ${sig(take.band,4)} Hz. `+(take.projection?tr('Projection résiduelle activée ; les modes manquants ne sont pas résolus.','Residual projection enabled; omitted modes are not resolved.'):tr('Base modale tronquée.','Truncated modal basis.'));
 const stats=take.stats[source],{x,y}=waveformEnvelope(samples,take.sr,1000);
 overviewPlot.x=[0,take.duration];overviewPlot.y=[-stats.peak*1.05||-1,stats.peak*1.05||1];overviewPlot.ylabel=unit;overviewPlot.curves=[{x,y,color:'#99b9a1'}];overviewPlot.draw();
}
const analysisOptions={settings:()=>project?.analysis||{},onView:()=>{syncAnalysisAxes();persist();},onSelection:()=>{syncAnalysisAxes();persist();},onSeek:t=>action(seekAudio)(t),cursor:cursorTime};
const analysisView=new SpectrogramView($('analysisSpectrogram'),analysisOptions),miniSpectrogram=new SpectrogramView($('spectrogram'),analysisOptions),overviewPlot=new LinePlot($('analysisOverview'),{x:[0,3],y:[-1,1],xlabel:'s',ylabel:'Pa'});
$('meshInterior').onclick=()=>{$('meshTop').checked=false;$('meshBack').checked=true;$('meshXray').checked=false;applyMeshOptions();};
$('openAnalysis').onclick=()=>switchTab('analysis');
$('analysisSource').onchange=()=>{$('listenSource').value=$('analysisSource').value;$('listenSource').dispatchEvent(new Event('change'));};
$('analysisPlay').onclick=action(async()=>{const offset=playOffset;stopAudio();analysisPlayback=true;playOffset=offset;await playTake();});
$('analysisPause').onclick=pauseAudio;$('analysisStop').onclick=stopAudio;
$('analysisSelectionPlay').onclick=action(async()=>{
 if(!take)return;const sel=project.analysis.selection;if(!sel||sel.t1-sel.t0<.01||sel.f1-sel.f0<10)throw new Error(tr('Tracer une sélection d’au moins 10 ms et 10 Hz.','Draw a selection of at least 10 ms and 10 Hz.'));
 stopAudio();playbackRegion={samples:extractBand(take[project.monitor.source],take.sr,sel),start:sel.t0,end:sel.t1};analysisPlayback=true;playOffset=sel.t0;await playTake();
});
$('analysisClear').onclick=()=>{delete project.analysis.selection;persist();renderAnalysis();};
$('analysisReset').onclick=()=>{if(!take)return;Object.assign(project.analysis,{tmin:0,tmax:take.duration,fmin:0,fmax:Math.min(take.sr/2,project.synthesis.fmax),scale:'linear'});persist();renderAnalysis();};
$('analysisSeek').oninput=e=>action(seekAudio)(Number(e.target.value));
$('analysisOverview').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();action(seekAudio)(overviewPlot.ux(e.clientX-r.left));});
$('analysisVolume').oninput=e=>{project.analysis.volume=Number(e.target.value);persist();if(analysisPlayback)updatePlaybackGain();};
for(const [id,key] of [['analysisTmin','tmin'],['analysisTmax','tmax'],['analysisFmin','fmin'],['analysisFmax','fmax']])$(id).onchange=()=>{const v=Number($(id).value);if(Number.isFinite(v)){project.analysis[key]=v;analysisView.clamp();persist();renderAnalysis();}};
$('analysisWav').onclick=()=>{if(!take)return;const sel=project.analysis.selection,samples=sel?extractBand(take[project.monitor.source],take.sr,sel):take[project.monitor.source];download(wav(listening(samples,take.sr,{...project.monitor,level:project.analysis.volume}),take.sr),filename()+'_'+project.monitor.source+(sel?'_selection':'_analysis')+'.wav');};
$('analysisPng').onclick=()=>{if(take)$('analysisSpectrogram').toBlob(blob=>download(blob,filename()+'_spectrogram.png','image/png'));};
const transportFrame=()=>{requestAnimationFrame(transportFrame);if(!take||tab!=='analysis')return;const t=cursorTime();$('analysisTime').textContent=sig(t,4)+' / '+sig(take.duration,4)+' s';if(document.activeElement!==$('analysisSeek'))$('analysisSeek').value=t;};requestAnimationFrame(transportFrame);

async function init(){catalog=await api('/api/catalog');project=clone(catalog.defaults.om);try{const saved=JSON.parse(localStorage.getItem('gmt-project'));if(saved?.schema==='gmt'){const compatible=normalizeProject(saved);const v=await api('/api/preview',{project:compatible});project=v.project||compatible;}}catch{}selected=project.braces[0]?.id;$('projectName').value=project.name;for(let i=0;i<6;i++)$('frfString').append(node('option',{value:i},String(6-i)));language();await refreshPreview();status();}
window.addEventListener('resize',()=>{if(take)renderAudio();});init().catch(e=>toast(tr('Démarrage impossible : ','Startup failed: ')+e.message,true));

let uqResult=null;
const uqPlot=new LinePlot($('uqPlot'),{x:[20,1600],y:[-100,-15],xlabel:'Hz',ylabel:'dB'});
$('runUQ').onclick=action(async()=>{if(!isReady())throw Error(tr('Calcul EF requis','FE solve required'));const settings={frequencyCV:+$('uqF').value,dampingCV:+$('uqZ').value,participationCV:+$('uqG').value,correlation:+$('uqCorrelation').value,samples:+$('uqN').value,seed:+$('uqSeed').value,fmin:+$('uqMin').value,fmax:+$('uqMax').value,port:selectedPort(),kind:$('frfType').value,loaded:$('frfLoad').value==='strings'},key=JSON.stringify([job,responseSignature()]);$('runUQ').disabled=true;$('uqInfo').textContent=tr('Calcul des tirages…','Computing samples…');try{const r=await api('/api/uncertainty',{id:job,project:clone(project),settings});if(key!==JSON.stringify([job,responseSignature()])){$('uqInfo').textContent=tr('Paramètres modifiés : relancer.','Parameters changed: run again.');return}uqResult={...r,projectName:project.name};uqPlot.x=[settings.fmin,settings.fmax];uqPlot.curves=['nominal','p10','p50','p90'].map((k,i)=>({x:r.frequency,y:r[k].map(v=>20*Math.log10(Math.max(1e-30,v))),color:['#293f36','#829bb1','#b16435','#829bb1'][i],label:k}));const ys=uqPlot.curves.flatMap(c=>c.y);uqPlot.y=[Math.min(...ys)-3,Math.max(...ys)+3];uqPlot.draw();$('uqInfo').textContent=`${r.samples} · P10 / P50 / P90 · ${tr('Contact','Contact')} ${settings.port+1} · ${settings.kind} · `+tr('Noir : nominal ; orange : médiane ; bleu : P10/P90.','Black: nominal; orange: median; blue: P10/P90.')+(r.clipped?` ${r.clipped} `+tr('paramètres bornés.','clipped parameters.'):'')}finally{$('runUQ').disabled=false}});
$('exportUQ').onclick=()=>{if(!uqResult)return;const r=uqResult;download(['f_Hz,nominal_SI,p10_SI,p50_SI,p90_SI',...r.frequency.map((f,i)=>[f,r.nominal[i],r.p10[i],r.p50[i],r.p90[i]].join(','))].join('\n'),(uqResult.projectName||'GMT').replace(/[^\p{L}\p{N}_-]/gu,'_')+'_UQ.csv','text/csv');download(JSON.stringify(r.settings,null,2),filename()+'_UQ_settings.json')};

